type IconName =
  | "building"
  | "chart"
  | "wallet"
  | "journal"
  | "check"
  | "arrow";

function Icon({ name }: { name: IconName }) {
  const paths: Record<IconName, ReactNode> = {
    building: (
      <>
        <path d="M4 20h16M6 20V9l6-5 6 5v11M9 20v-6h6v6" />
        <path d="M9 10h.01M15 10h.01" />
      </>
    ),
    chart: (
      <>
        <path d="M4 19V5M4 19h16" />
        <path d="m7 15 3-4 3 2 5-7" />
      </>
    ),
    wallet: (
      <>
        <path d="M4 7h14a2 2 0 0 1 2 2v9H6a2 2 0 0 1-2-2V7Z" />
        <path d="M4 7a2 2 0 0 1 2-2h10v2M15 12h5" />
      </>
    ),
    journal: (
      <>
        <path d="M6 3h11a2 2 0 0 1 2 2v16H7a2 2 0 0 1-2-2V4" />
        <path d="M9 8h6M9 12h6M9 16h4" />
      </>
    ),
    check: <path d="m5 12 4 4L19 6" />,
    arrow: (
      <>
        <path d="M5 12h14" />
        <path d="M14 7l5 5-5 5" />
      </>
    ),
  };

  return (
    <svg
      viewBox="0 0 24 24"
      aria-hidden="true"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      {paths[name]}
    </svg>
  );
}

